import { Router } from "express";
import { createActivityLog, deleteActivityLog, getActivityLogById, getActivityLogs, updateActivityLog, } from "../controllers/activity-log.controller";
import { requiredAuth } from "../middleware/auth.middleware";
import { requireRole } from "../middleware/role.middleware";
const router = Router();
router.post("/", requiredAuth, requireRole("client", "engineer", "supervisor", "supplier", "admin"), createActivityLog);
router.get("/", requiredAuth, requireRole("client", "engineer", "supervisor", "supplier", "admin"), getActivityLogs);
router.get("/:id", requiredAuth, requireRole("client", "engineer", "supervisor", "supplier", "admin"), getActivityLogById);
router.put("/:id", requiredAuth, requireRole("admin"), updateActivityLog);
router.delete("/:id", requiredAuth, requireRole("admin"), deleteActivityLog);
export default router;
